namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Category is required.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Description is required.")]
    [StringLength(500, ErrorMessage = "Description must be 500 characters or fewer.")]
    public string Description { get; set; } = string.Empty;

    [Required(ErrorMessage = "At least one ingredient is required.")]
    [MinLength(1, ErrorMessage = "At least one ingredient is required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "At least one step is required.")]
    [MinLength(1, ErrorMessage = "At least one step is required.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1,
                Title = "Classic Margherita Pizza",
                Category = "Italian",
                Description = "A simple and delicious pizza with fresh mozzarella, tomatoes, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps =
                [
                    "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                    "Stretch the dough into a 12-inch circle on a floured surface.",
                    "Spread crushed tomatoes evenly over the dough, leaving a 1-inch border.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10–12 minutes until the crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and a drizzle of olive oil before serving."
                ],
                TotalRatings = 12,
                RatingSum = 53
            },
            new Recipe
            {
                Id = 2,
                Title = "Chicken Tikka Masala",
                Category = "Indian",
                Description = "Tender chicken pieces in a rich, creamy tomato-spiced sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps =
                [
                    "Marinate chicken in yogurt, garam masala, cumin, and turmeric for at least 1 hour.",
                    "Grill or broil the chicken until charred and cooked through.",
                    "Sauté onion, garlic, and ginger in a large pan until soft.",
                    "Add tomato sauce and spices, simmer for 15 minutes.",
                    "Stir in heavy cream and add the cooked chicken.",
                    "Simmer for 10 more minutes and serve over basmati rice."
                ],
                TotalRatings = 8,
                RatingSum = 37
            },
            new Recipe
            {
                Id = 3,
                Title = "Beef Tacos",
                Category = "Mexican",
                Description = "Seasoned ground beef tacos with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps =
                [
                    "Brown ground beef in a skillet over medium-high heat.",
                    "Add taco seasoning and water, simmer until thickened.",
                    "Warm tortillas in a dry skillet or microwave.",
                    "Fill tortillas with seasoned beef.",
                    "Top with shredded lettuce, diced tomato, cheese, sour cream, and salsa."
                ],
                TotalRatings = 15,
                RatingSum = 62
            },
            new Recipe
            {
                Id = 4,
                Title = "Pad Thai",
                Category = "Thai",
                Description = "Classic stir-fried rice noodles with shrimp, peanuts, and tangy sauce.",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Sugar", "Lime"],
                Steps =
                [
                    "Soak rice noodles in warm water for 30 minutes, then drain.",
                    "Mix tamarind paste, fish sauce, and sugar to make the sauce.",
                    "Stir-fry shrimp in a hot wok until pink, then set aside.",
                    "Scramble eggs in the same wok.",
                    "Add noodles and sauce, toss until noodles are tender.",
                    "Return shrimp, add bean sprouts and green onions, toss to combine.",
                    "Serve topped with crushed peanuts and a squeeze of lime."
                ],
                TotalRatings = 6,
                RatingSum = 27
            },
            new Recipe
            {
                Id = 5,
                Title = "Chocolate Lava Cake",
                Category = "Desserts",
                Description = "Rich individual chocolate cakes with a molten center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps =
                [
                    "Preheat oven to 425°F (220°C). Butter and flour four ramekins.",
                    "Melt chocolate and butter together in a double boiler.",
                    "Whisk eggs, sugar, and vanilla until thick and pale.",
                    "Fold the chocolate mixture into the egg mixture.",
                    "Gently fold in flour until just combined.",
                    "Divide batter among ramekins and bake for 12–14 minutes.",
                    "Let rest 1 minute, then invert onto plates and serve immediately."
                ],
                TotalRatings = 20,
                RatingSum = 94
            },
            new Recipe
            {
                Id = 6,
                Title = "Caesar Salad",
                Category = "American",
                Description = "Crisp romaine lettuce with homemade Caesar dressing and crunchy croutons.",
                Ingredients = ["Romaine lettuce", "Parmesan cheese", "Croutons", "Egg yolk", "Garlic", "Anchovy paste", "Dijon mustard", "Lemon juice", "Olive oil"],
                Steps =
                [
                    "Whisk egg yolk, garlic, anchovy paste, Dijon mustard, and lemon juice.",
                    "Slowly drizzle in olive oil while whisking to emulsify.",
                    "Tear romaine into bite-sized pieces and place in a large bowl.",
                    "Toss with dressing until evenly coated.",
                    "Top with freshly grated Parmesan and croutons."
                ],
                TotalRatings = 10,
                RatingSum = 40
            }
        ];
        _nextId = 7;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public IReadOnlyList<Recipe> GetAllRecipes()
    {
        return _recipes.AsReadOnly();
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Description = submission.Description,
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

