<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (Recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 g-4">
        @foreach (var recipe in Recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text">@recipe.Description</p>
                        <div class="d-flex justify-content-between align-items-center">
                            <span class="text-warning">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    @(i <= Math.Round(recipe.AverageRating) ? "★" : "☆")
                                }
                                <small class="text-muted">(@recipe.TotalRatings ratings)</small>
                            </span>
                            <a href="@($"recipe/{recipe.Id}")" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<RecipeShare.Models.Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{RecipeId:int}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-secondary">Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="@($"category/{Recipe.Category}")">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>
    <p class="lead text-muted">@Recipe.Description</p>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in Recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>

            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">Rating</h5></div>
                <div class="card-body">
                    <p class="mb-1">
                        <span class="text-warning fs-5">
                            @for (int i = 1; i <= 5; i++)
                            {
                                @(i <= Math.Round(Recipe.AverageRating) ? "★" : "☆")
                            }
                        </span>
                        <span class="text-muted">@Recipe.AverageRating.ToString("0.0") (@Recipe.TotalRatings ratings)</span>
                    </p>
                    <hr />
                    <StarRating RecipeId="Recipe.Id" />
                </div>
            </div>
        </div>

        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Instructions</h5></div>
                <div class="card-body">
                    <ol class="mb-0">
                        @foreach (var step in Recipe.Steps)
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private RecipeShare.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

@if (Submitted)
{
    <div class="alert alert-success">
        ✅ Thanks for your rating of @SelectedStars star(s)!
    </div>
}
else
{
    <p class="mb-1">Rate this recipe:</p>
    <div style="cursor: pointer; font-size: 1.5rem;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="@(star <= HoveredStar ? "text-warning" : "text-muted")"
                  @onmouseover="() => HoveredStar = star"
                  @onmouseout="() => HoveredStar = 0"
                  @onclick="() => SubmitRating(star)">★</span>
        }
    </div>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int HoveredStar;
    private int SelectedStars;
    private bool Submitted;

    private void SubmitRating(int stars)
    {
        SelectedStars = stars;
        RecipeService.AddRating(RecipeId, stars);
        Submitted = true;
    }
}

